-- Canonical student sectioning v2: scoped candidates, online/batch resectioning, conflict repair and health.
alter table public.student_schedule_enrollments add column if not exists request_id uuid references public.student_course_requests(id) on delete set null;
alter table public.student_course_requests add column if not exists scope_mode text not null default 'HOME_CLASS';
do $$begin if not exists(select 1 from pg_constraint where conname='student_course_requests_scope_mode_check') then alter table public.student_course_requests add constraint student_course_requests_scope_mode_check check(scope_mode in('HOME_CLASS','OFFERING','CROSS_CLASS'));end if;end$$;
alter table public.schedule_generation_settings add column if not exists section_balance_penalty integer not null default 5,add column if not exists section_change_penalty integer not null default 25;
create index if not exists idx_student_enrollment_request on public.student_schedule_enrollments(institution_code,request_id) where active and request_id is not null;
create index if not exists idx_student_request_solver on public.student_course_requests(institution_code,student_id,request_kind,priority) where active;
create index if not exists idx_student_enrollment_solver on public.student_schedule_enrollments(institution_code,student_id,teacher_assignment_id) where active;

create or replace function public.get_student_section_candidates_v2(p_request_id uuid) returns table(assignment_id uuid,teacher_id uuid,capacity integer,load integer,feasible boolean,hard_reasons text[],medium_penalty numeric,soft_penalty numeric,is_current boolean) language sql stable security definer set search_path=public as $$with q0 as(select r.*,s.class_id home_class_id from public.student_course_requests r join public.students s on s.id=r.student_id and s.active where r.id=p_request_id and r.active and tenant_row_allowed(r.institution_code) and tenant_row_allowed(s.institution_code) and (is_manager_or_admin() or has_permission('schedule.generate'))),q as(select q0.*,(select cr.offering_rule_id from public.class_course_requirements cr where cr.class_id=q0.home_class_id and cr.course_id=q0.course_id and tenant_row_allowed(cr.institution_code) order by cr.id limit 1)home_offering_rule_id from q0),cfg as(select section_balance_penalty,section_change_penalty from public.schedule_generation_settings where id=true limit 1),cand as(select ta.id assignment_id,ta.teacher_id,q.student_id,q.course_id,coalesce(ta.section_capacity,(select min(c.capacity) from public.teacher_schedule ts join public.classrooms c on c.id=ts.classroom_id where ts.active and ts.teacher_assignment_id=ta.id))::int capacity,(select count(*)::int from public.student_schedule_enrollments e where e.active and e.teacher_assignment_id=ta.id and e.student_id<>q.student_id)load,exists(select 1 from public.teacher_schedule ts where ts.active and ts.teacher_assignment_id=ta.id)has_schedule,exists(select 1 from public.student_schedule_enrollments e join public.teacher_course_assignments ota on ota.id=e.teacher_assignment_id join public.class_course_requirements ocr on ocr.id=ota.class_course_requirement_id where e.active and e.locked and e.student_id=q.student_id and ocr.course_id=q.course_id and e.teacher_assignment_id<>ta.id)locked_elsewhere,exists(select 1 from public.student_free_time_requests f join public.teacher_schedule ts on ts.teacher_assignment_id=ta.id and ts.active where f.active and f.student_id=q.student_id and f.mode='HARD' and f.weekday=ts.weekday and ts.period=any(f.periods))hard_free,exists(select 1 from public.student_schedule_enrollments e join public.teacher_course_assignments ota on ota.id=e.teacher_assignment_id join public.class_course_requirements ocr on ocr.id=ota.class_course_requirement_id join public.teacher_schedule old on old.teacher_assignment_id=e.teacher_assignment_id and old.active join public.teacher_schedule nw on nw.teacher_assignment_id=ta.id and nw.active where e.active and e.student_id=q.student_id and ocr.course_id<>q.course_id and old.weekday=nw.weekday and old.period=nw.period)time_conflict,coalesce((select sum(f.weight) from public.student_free_time_requests f join public.teacher_schedule ts on ts.teacher_assignment_id=ta.id and ts.active where f.active and f.student_id=q.student_id and f.mode='MEDIUM' and f.weekday=ts.weekday and ts.period=any(f.periods)),0)::numeric medium_free,coalesce((select sum(f.weight) from public.student_free_time_requests f join public.teacher_schedule ts on ts.teacher_assignment_id=ta.id and ts.active where f.active and f.student_id=q.student_id and f.mode='SOFT' and f.weekday=ts.weekday and ts.period=any(f.periods)),0)::numeric soft_free,(select e.teacher_assignment_id from public.student_schedule_enrollments e join public.teacher_course_assignments ota on ota.id=e.teacher_assignment_id join public.class_course_requirements ocr on ocr.id=ota.class_course_requirement_id where e.active and e.student_id=q.student_id and ocr.course_id=q.course_id order by e.locked desc,e.updated_at desc limit 1)current_assignment from q join public.class_course_requirements cr on cr.course_id=q.course_id and tenant_row_allowed(cr.institution_code) and(q.scope_mode='CROSS_CLASS' or cr.class_id=q.home_class_id or(q.scope_mode='OFFERING' and q.home_offering_rule_id is not null and cr.offering_rule_id=q.home_offering_rule_id)) join public.teacher_course_assignments ta on ta.class_course_requirement_id=cr.id and tenant_row_allowed(ta.institution_code)),scored as(select c.*,array_remove(array[case when not has_schedule then'NO_TIMETABLE'end,case when capacity is null then'CAPACITY_UNKNOWN'end,case when capacity is not null and load>=capacity then'SECTION_FULL'end,case when locked_elsewhere then'LOCKED_SECTION'end,case when hard_free then'HARD_FREE_TIME'end,case when time_conflict then'TIME_CONFLICT'end],null)::text[] reasons from cand c),outq as(select assignment_id,teacher_id,capacity,load,cardinality(reasons)=0 feasible,reasons hard_reasons,medium_free medium_penalty,(soft_free+case when capacity is not null and capacity>0 then(load::numeric/capacity::numeric)*coalesce(cfg.section_balance_penalty,5)else 0 end+case when current_assignment is not null and current_assignment<>assignment_id then coalesce(cfg.section_change_penalty,25)else 0 end)::numeric soft_penalty,current_assignment=assignment_id is_current from scored cross join cfg)select * from outq order by feasible desc,medium_penalty,soft_penalty,load,assignment_id$$;

create or replace function public.section_student_v2(p_student_id uuid,p_replace_solver boolean default true) returns jsonb language plpgsql security definer set search_path=public as $$declare q record;c record;v_selected uuid[]:='{}';v_groups text[]:='{}';v_assigned int:=0;v_unassigned int:=0;v_changed int:=0;v_old uuid;v_reasons text;begin if not(is_manager_or_admin() or has_permission('schedule.generate'))then raise exception'NOT_AUTHORIZED';end if;perform pg_advisory_xact_lock(hashtextextended(current_tenant_code()||':student-sectioning',0));if not exists(select 1 from public.students s where s.id=p_student_id and s.active and tenant_row_allowed(s.institution_code))then raise exception'STUDENT_NOT_FOUND_IN_TENANT';end if;delete from public.student_sectioning_issues where student_id=p_student_id and institution_code=current_tenant_code();select coalesce(array_agg(distinct r.alternative_group)filter(where r.alternative_group is not null),'{}')into v_groups from public.student_schedule_enrollments e join public.teacher_course_assignments ta on ta.id=e.teacher_assignment_id join public.class_course_requirements cr on cr.id=ta.class_course_requirement_id join public.student_course_requests r on r.student_id=e.student_id and r.course_id=cr.course_id and r.active where e.student_id=p_student_id and e.active and e.locked and tenant_row_allowed(e.institution_code);for q in select r.* from public.student_course_requests r where r.student_id=p_student_id and r.active and tenant_row_allowed(r.institution_code) order by case upper(r.request_kind)when'PRIMARY'then 0 when'ALTERNATIVE'then 1 else 2 end,r.priority,r.id loop if q.alternative_group is not null and q.alternative_group=any(v_groups)then continue;end if;select e.teacher_assignment_id into v_old from public.student_schedule_enrollments e join public.teacher_course_assignments ta on ta.id=e.teacher_assignment_id join public.class_course_requirements cr on cr.id=ta.class_course_requirement_id where e.student_id=p_student_id and e.active and cr.course_id=q.course_id order by e.locked desc,e.updated_at desc limit 1;select * into c from public.get_student_section_candidates_v2(q.id)x where x.feasible order by x.medium_penalty,x.soft_penalty,x.load,x.assignment_id limit 1;if c.assignment_id is null then select string_agg(coalesce(array_to_string(x.hard_reasons,','),'UNKNOWN'),'; ' order by x.medium_penalty,x.soft_penalty)into v_reasons from public.get_student_section_candidates_v2(q.id)x;insert into public.student_sectioning_issues(institution_code,student_id,request_id,code,detail)values(current_tenant_code(),p_student_id,q.id,'NO_FEASIBLE_SECTION',coalesce(v_reasons,'Bu ders için section/takvim bulunamadı.'));else update public.student_schedule_enrollments e set active=false,updated_at=now() where e.student_id=p_student_id and e.active and not e.locked and e.teacher_assignment_id<>c.assignment_id and exists(select 1 from public.teacher_course_assignments ta join public.class_course_requirements cr on cr.id=ta.class_course_requirement_id where ta.id=e.teacher_assignment_id and cr.course_id=q.course_id);insert into public.student_schedule_enrollments(institution_code,student_id,teacher_assignment_id,request_id,source,active)values(current_tenant_code(),p_student_id,c.assignment_id,q.id,'solver',true)on conflict(institution_code,student_id,teacher_assignment_id)do update set request_id=excluded.request_id,active=true,source=case when public.student_schedule_enrollments.locked then public.student_schedule_enrollments.source else'solver'end,updated_at=now();v_selected:=array_append(v_selected,c.assignment_id);if v_old is not null and v_old<>c.assignment_id then v_changed:=v_changed+1;end if;v_assigned:=v_assigned+1;if q.alternative_group is not null then delete from public.student_sectioning_issues i using public.student_course_requests rr where i.student_id=p_student_id and i.request_id=rr.id and rr.student_id=p_student_id and rr.alternative_group=q.alternative_group;v_groups:=array_append(v_groups,q.alternative_group);end if;end if;c:=null;v_old:=null;end loop;if p_replace_solver then update public.student_schedule_enrollments set active=false,updated_at=now() where student_id=p_student_id and active and source='solver' and not locked and not(teacher_assignment_id=any(v_selected));end if;select count(*)::int into v_unassigned from public.student_sectioning_issues where institution_code=current_tenant_code() and student_id=p_student_id;return jsonb_build_object('student_id',p_student_id,'assigned',v_assigned,'unassigned',v_unassigned,'changed',v_changed);end$$;

create or replace function public.section_students_batch_v2(p_replace_solver boolean default true)returns jsonb language plpgsql security definer set search_path=public as $$declare s record;r jsonb;v_students int:=0;v_assigned int:=0;v_unassigned int:=0;v_changed int:=0;begin if not(is_manager_or_admin() or has_permission('schedule.generate'))then raise exception'NOT_AUTHORIZED';end if;delete from public.student_sectioning_issues where institution_code=current_tenant_code();for s in select st.id,coalesce((select sum((select count(*) from public.get_student_section_candidates_v2(r.id)c where c.feasible))from public.student_course_requests r where r.active and r.student_id=st.id),0)feasible_count,coalesce((select count(*)from public.student_course_requests r where r.active and r.student_id=st.id),0)req_count from public.students st where st.active and tenant_row_allowed(st.institution_code)and exists(select 1 from public.student_course_requests r where r.active and r.student_id=st.id and tenant_row_allowed(r.institution_code))order by feasible_count,req_count desc,st.id loop r:=public.section_student_v2(s.id,p_replace_solver);v_students:=v_students+1;v_assigned:=v_assigned+coalesce((r->>'assigned')::int,0);v_unassigned:=v_unassigned+coalesce((r->>'unassigned')::int,0);v_changed:=v_changed+coalesce((r->>'changed')::int,0);end loop;return jsonb_build_object('students',v_students,'assigned',v_assigned,'unassigned',v_unassigned,'changed',v_changed);end$$;
create or replace function public.repair_student_sectioning_conflicts_v2()returns jsonb language plpgsql security definer set search_path=public as $$declare s record;r jsonb;v_students int:=0;v_before int;v_after int;v_changed int:=0;begin if not(is_manager_or_admin() or has_permission('schedule.generate'))then raise exception'NOT_AUTHORIZED';end if;select count(*)::int into v_before from public.get_schedule_student_conflict_report_v2();for s in select distinct student_id from public.get_schedule_student_conflict_report_v2()order by student_id loop r:=public.section_student_v2(s.student_id,true);v_students:=v_students+1;v_changed:=v_changed+coalesce((r->>'changed')::int,0);end loop;select count(*)::int into v_after from public.get_schedule_student_conflict_report_v2();return jsonb_build_object('students_resectioned',v_students,'conflicts_before',v_before,'conflicts_after',v_after,'changed',v_changed);end$$;
create or replace function public.section_students_batch_v1(p_replace_solver boolean default true)returns jsonb language sql security definer set search_path=public as $$select public.section_students_batch_v2(p_replace_solver)$$;

create or replace function public.get_schedule_assignment_student_conflict_weights_v2()returns table(left_assignment_id uuid,right_assignment_id uuid,student_weight bigint,severity_weight numeric)language sql stable security definer set search_path=public as $$with e as(select e.student_id,e.teacher_assignment_id,r.course_id,coalesce(req.importance,1::numeric)importance,coalesce(req.allow_overlap,false)allow_overlap from public.student_schedule_enrollments e join public.teacher_course_assignments ta on ta.id=e.teacher_assignment_id join public.class_course_requirements r on r.id=ta.class_course_requirement_id left join lateral(select bool_or(scr.allow_overlap)allow_overlap,max((case upper(scr.request_kind)when'PRIMARY'then 4 when'ALTERNATIVE'then 2 when'SUBSTITUTE'then 1 else 1 end)::numeric/greatest(scr.priority,1))importance from public.student_course_requests scr where scr.active and scr.student_id=e.student_id and scr.course_id=r.course_id and tenant_row_allowed(scr.institution_code))req on true where e.active and tenant_row_allowed(e.institution_code)),pairs as(select least(a.teacher_assignment_id,b.teacher_assignment_id)l,greatest(a.teacher_assignment_id,b.teacher_assignment_id)r,count(distinct a.student_id)::bigint students,sum(least(a.importance,b.importance))::numeric severity from e a join e b on b.student_id=a.student_id and a.teacher_assignment_id<b.teacher_assignment_id where not a.allow_overlap and not b.allow_overlap group by 1,2)select l,r,students,severity from pairs where students>0 order by severity desc,students desc,l,r$$;
create or replace function public.get_student_sectioning_health_v2()returns table(students_with_requests integer,active_requests integer,active_enrollments integer,open_issues integer,conflict_events integer,locked_enrollments integer,sections_at_capacity integer)language sql stable security definer set search_path=public as $$select(select count(distinct student_id)::int from public.student_course_requests where active and tenant_row_allowed(institution_code)),(select count(*)::int from public.student_course_requests where active and tenant_row_allowed(institution_code)),(select count(*)::int from public.student_schedule_enrollments where active and tenant_row_allowed(institution_code)),(select count(*)::int from public.student_sectioning_issues where tenant_row_allowed(institution_code)),(select count(*)::int from public.get_schedule_student_conflict_report_v2()),(select count(*)::int from public.student_schedule_enrollments where active and locked and tenant_row_allowed(institution_code)),(select count(*)::int from(select ta.id,coalesce(ta.section_capacity,(select min(c.capacity)from public.teacher_schedule ts join public.classrooms c on c.id=ts.classroom_id where ts.active and ts.teacher_assignment_id=ta.id))cap,(select count(*)from public.student_schedule_enrollments e where e.active and e.teacher_assignment_id=ta.id)load from public.teacher_course_assignments ta where tenant_row_allowed(ta.institution_code))x where x.cap is not null and x.load>=x.cap)$$;
revoke all on function public.get_student_section_candidates_v2(uuid),public.section_student_v2(uuid,boolean),public.section_students_batch_v2(boolean),public.repair_student_sectioning_conflicts_v2(),public.get_student_sectioning_health_v2() from public;
grant execute on function public.get_student_section_candidates_v2(uuid),public.section_student_v2(uuid,boolean),public.section_students_batch_v2(boolean),public.repair_student_sectioning_conflicts_v2(),public.get_student_sectioning_health_v2() to authenticated;
